const icons={
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m14 5-7 7 7 7M7 12h13"/>',chevron:'<path d="m8 5 7 7-7 7"/>',down:'<path d="m7 10 5 5 5-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.2 4.2"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m15.5 8.5-2 5-5 2 2-5z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',pin:'<path d="M18.5 10c0 5-6.5 11-6.5 11S5.5 15 5.5 10a6.5 6.5 0 1 1 13 0z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m6 10 5-3 3 5 4 2m-7-7-1 7-4 6m4-6 5 3 1 5"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16"/>',coffee:'<path d="M4 8h12v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM16 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.arrow}</svg>`;
const store={get(k,d){try{return localStorage.getItem('roam.'+k)??d}catch{return d}},set(k,v){try{localStorage.setItem('roam.'+k,v)}catch{}}};
let saved=store.get('saved','false')==='true',locationName=store.get('location','Lisbon'),pace=store.get('pace','Easy going'),planDate=store.get('date','2026-11-07'),filter='All',query='',detailTab='itinerary',toastTimer;
const view=document.getElementById('view');
const trips={coast:{title:'The quiet coast',split:'The quiet<br>coast',region:'AZENHAS DO MAR, PORTUGAL',image:'../assets/roam-coast.png',alt:'Original generated scene of a sunlit coastal trail above blue water',distance:'40 min',walk:'4.2 km',duration:'One day',mood:'Easy going',intro:'Salt in the air. Nothing on the clock.<br>A day of cliff paths, good coffee and sea views.',overview:'Take the road less hurried.<br>We found a little stretch of coast that feels a world away.',packing:'Comfortable shoes, a light layer and water. The cliff path is exposed; stay on marked trails. All places and times are illustrative.',stops:[['09:30','Coffee, with a view','Find a sunny corner in the village. A slow coffee before the day opens up.','45 MIN · VILLAGE'],['11:00','Follow the Atlantic','A gentle coastal walk, with a few good reasons to stop and look back.','4.2 KM · EASY PACE'],['13:00','A table by the ocean','Leave a little room for a long lunch. No reservation included.','LUNCH · AT YOUR PACE'],['15:30','One last blue hour','Wander down toward the beach, then head back whenever you feel ready.','FREE TIME']]},city:{title:'A slow morning in Alfama',split:'A slow morning<br>in Alfama',region:'ALFAMA, LISBON',image:'../assets/city.svg',alt:'Original illustration of terracotta rooftops and a Lisbon tram',distance:'15 min',walk:'2.1 km',duration:'Half day',mood:'City wandering',intro:'Take a turn. Then another.<br>Small streets, tiled walls and a very good pastry.',overview:'No checklist. Just a pocket of the city worth getting lost in.',packing:'Comfortable shoes for cobblestones. The route includes steps; an accessible alternative is not verified in this prototype.',stops:[['09:00','A pastry worth a detour','Start with coffee and something warm from the oven.','30 MIN · COFFEE'],['10:00','Streets without a hurry','Follow a short loop through quiet lanes and tiled facades.','2.1 KM · STEPS'],['11:30','A view over the rooftops','Find a bench, watch the river and let the morning stretch.','FREE TIME']]}};
function refreshIcons(){document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon))}
function notify(message){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
function nav(){const route=(location.hash.slice(1)||'discover');document.querySelectorAll('.bottom-nav button').forEach(b=>{if(b.dataset.route===(route.startsWith('trip')?'discover':route))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.getElementById('saved-count').hidden=!saved}
function favorite(){return `<button class="icon-button favorite" data-save aria-label="${saved?'Remove The quiet coast from plans':'Save The quiet coast'}" aria-pressed="${saved}">${icon('bookmark')}</button>`}
function route(name){if(location.hash.slice(1)===name){render()}else location.hash=name}
function tripCard(key='coast',compact=false){const t=trips[key];return `<article><div class="trip-photo${compact?' saved-cover':''}"><button data-trip="${key}" aria-label="View ${t.title}"><img src="${t.image}" alt="${t.alt}"></button><span class="photo-kicker">A DAY WELL SPENT</span>${key==='coast'?favorite():''}<span class="photo-caption">${t.region.split(',')[0]} <span class="dot"></span> ${t.distance.toUpperCase()} AWAY</span></div><div class="trip-name"><h2><button class="text-link" data-trip="${key}">${t.title}</button></h2><button class="icon-button" data-trip="${key}" aria-label="Open itinerary">${icon('arrow')}</button></div><p class="trip-meta">${icon('clock')} ${t.duration} <span>·</span> ${t.mood} <span>·</span> ${t.walk} walking</p></article>`}
function collection(){const el=document.getElementById('collection');if(!el)return;const q=query.toLowerCase();const showCoast=['All','Coast','Nature'].includes(filter)&&(!q||['coast','quiet','atlantic','azenh','sea','beach','lisbon'].some(s=>s.includes(q)||q.includes(s)));const showCity=['All','City'].includes(filter)&&(!q||['alfama','city','lisbon','coffee','morning'].some(s=>s.includes(q)||q.includes(s)));el.innerHTML=(showCoast?tripCard():'' )+(showCity?`${showCoast?'<div class="section-title"><h3>A little closer</h3><span>In your city</span></div>':''}<button class="local-trip" data-trip="city"><img class="local-thumb" src="../assets/city.svg" alt="Original Lisbon rooftop illustration"><span><b>A slow morning<br>in Alfama</b><small>15 min away · Coffee & cobblestones</small></span>${icon('arrow')}</button>`:'');if(!showCoast&&!showCity)el.innerHTML=`<div class="no-results">${icon('compass')}<h2>Not on this little map.</h2><p>Try “coast”, “coffee” or “Lisbon”.</p><button class="secondary" data-reset>See all daytrips</button></div>`}
function discover(){view.innerHTML=`<header class="home-header"><span class="wordmark">roam<span style="color:var(--action)">.</span></span><button class="location-trigger" data-location-open aria-label="Change starting location">${icon('pin')} Near ${locationName} ${icon('down')}</button></header><section class="intro"><p class="overline">LESS PLANNING. MORE LIVING.</p><h1>A little further.<br>A little <em>freer.</em></h1></section><label class="search">${icon('search')}<input id="search" aria-label="Search daytrips" placeholder="Where to wander?" value="${query.replaceAll('"','&quot;')}"></label><div class="categories" aria-label="Trip categories">${['All','Coast','Nature','City'].map(c=>`<button class="category" data-filter="${c}" aria-pressed="${c===filter}">${c}</button>`).join('')}</div><section id="collection" class="collection" aria-label="Curated daytrips"></section>`;collection();document.getElementById('search').addEventListener('input',e=>{query=e.target.value;collection()})}
function detail(key){const t=trips[key];view.innerHTML=`<div class="detail-photo"><img src="${t.image}" alt="${t.alt}"><div class="detail-top"><button class="icon-button" data-route="discover" aria-label="Back to discovery">${icon('back')}</button>${key==='coast'?favorite():''}</div><div class="detail-hero-title"><p>${t.region}</p><h1 tabindex="-1">${t.split}</h1></div></div><section class="detail-content"><p class="intro-line">${t.intro}</p><div class="facts"><div>${icon('clock')}<b>${t.duration}</b><small>Just enough time</small></div><div>${icon('walk')}<b>${t.walk}</b><small>On foot</small></div><div>${icon('sun')}<b>${key==='coast'?'22°':'20°'}</b><small>Illustrative forecast</small></div></div><div class="detail-tabs" role="tablist" aria-label="Trip information"><button id="tab-itinerary" role="tab" aria-controls="trip-panel" aria-selected="${detailTab==='itinerary'}" data-tab="itinerary">Your day</button><button id="tab-overview" role="tab" aria-controls="trip-panel" aria-selected="${detailTab==='overview'}" data-tab="overview">Good to know</button></div><div id="trip-panel" role="tabpanel" aria-labelledby="tab-${detailTab}">${detailTab==='itinerary'?`<ol class="timeline">${t.stops.map(([time,title,desc,tag])=>`<li><time>${time}</time><div><b>${title}</b><p>${desc}</p><small>${tag}</small></div></li>`).join('')}</ol>`:`<p class="overview-copy">${t.overview}</p><div class="packing"><b>Bring a little common sense.</b>${t.packing}</div><p class="intro-line" style="margin-top:18px">A suggested day, not a booking. Check local conditions before heading out.</p>`}</div>${key==='coast'?`<div class="save-bar"><button class="primary" data-plan>${icon(saved?'check':'bookmark')}${saved?'View your saved day':'Save this day'} ${icon('arrow')}</button></div>`:`<div class="save-bar"><button class="primary" data-route="discover">Back to nearby trips ${icon('arrow')}</button></div>`}</section>`}
function savedPage(){view.innerHTML=`<header class="page-heading"><p class="overline">MAKE A LITTLE ROOM</p><h1>Your next<br><em style="font-weight:400">good day.</em></h1><p class="saved-intro">${saved?'One little escape, ready when you are.':'Keep a few possibilities close.'}</p></header>${saved?`<section class="collection">${tripCard('coast',true)}<div class="saved-note">${icon('check')} Saved on this device. No booking needed.</div><label class="overline" for="plan-date">MAKE IT A DATE</label><input class="day-field" id="plan-date" type="date" value="${planDate}" aria-describedby="date-note"><p class="muted" id="date-note" style="font-size:11px;margin:7px 0 20px">Your plan. Your pace. Change it anytime.</p><div class="plan-actions"><button class="primary" data-trip="coast">Open itinerary ${icon('arrow')}</button><button class="secondary remove" data-remove>Remove</button></div></section>`:`<section class="empty">${icon('bookmark')}<h2>Leave a day open.</h2><p>A coastal walk, a slow coffee.<br>Save something worth stepping out for.</p><button class="primary" data-route="discover">Find your little escape ${icon('arrow')}</button></section>`}`;document.getElementById('plan-date')?.addEventListener('change',e=>{if(e.target.value){planDate=e.target.value;store.set('date',planDate);notify('Your day has a date. You can change it anytime.')}})}
function you(){view.innerHTML=`<header class="page-heading"><p class="overline">YOUR KIND OF WANDER</p><h1>A little<br>more you.</h1></header><div class="profile-mark">r.</div><p class="profile-note">The best plans leave<br>room for a detour.</p><section class="pref-section"><h2>Set your pace.</h2><div class="categories">${['Easy going','A little adventure'].map(p=>`<button class="category" data-pace="${p}" aria-pressed="${pace===p}">${p}</button>`).join('')}</div><p>Your preference stays on this device.</p></section><section class="pref-section"><h2>Starting from</h2><button class="secondary" data-location-open>${icon('pin')} ${locationName}</button></section><section class="pref-section"><h2>A small collection.</h2><p>Roam is an original local prototype with illustrative destinations. No account, live location, forecast or reservations are connected.</p><a href="../index.html" style="font-size:12px">About this prototype ${'↗'}</a></section>`}
function render(){const r=location.hash.slice(1)||'discover';if(r==='saved')savedPage();else if(r==='you')you();else if(r==='trip-city')detail('city');else if(r==='trip')detail('coast');else discover();nav();refreshIcons();window.scrollTo(0,0);view.querySelector('h1')?.setAttribute('tabindex','-1')}
function updateSaved(next,message){saved=next;store.set('saved',String(next));nav();document.querySelectorAll('[data-save]').forEach(b=>{b.setAttribute('aria-pressed',String(next));b.setAttribute('aria-label',next?'Remove The quiet coast from plans':'Save The quiet coast')});if(message)notify(message)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.route)route(b.dataset.route);else if(b.dataset.trip){detailTab='itinerary';route(b.dataset.trip==='city'?'trip-city':'trip')}else if(b.hasAttribute('data-save')){updateSaved(!saved,saved?'Removed from My plans.':'A little escape, saved to My plans.')}else if(b.hasAttribute('data-plan')){if(!saved)updateSaved(true);route('saved');notify('Your day is saved on this device.')}else if(b.hasAttribute('data-remove')){updateSaved(false);savedPage();notify('Plan removed. You can save it again anytime.')}else if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.filter===filter)));collection()}else if(b.hasAttribute('data-reset')){filter='All';query='';discover()}else if(b.dataset.tab){detailTab=b.dataset.tab;const active=location.hash==='#trip-city'?'city':'coast';detail(active);document.getElementById('tab-'+detailTab).focus()}else if(b.hasAttribute('data-location-open')){document.getElementById('location-dialog').showModal()}else if(b.hasAttribute('data-close')){document.getElementById('location-dialog').close()}else if(b.dataset.location){locationName=b.dataset.location;store.set('location',locationName);document.getElementById('location-dialog').close();render();notify('Starting point set to '+locationName+'.')}else if(b.dataset.pace){pace=b.dataset.pace;store.set('pace',pace);you();notify('A little more your pace.')}});
window.addEventListener('hashchange',render);render();
